//
  const SM_CONFIG = {
    businessName: "SM Traders",
    tagline: "Electrical & Solar Solutions",
    owners: "Mangesh Yendhe & Omkar Yendhe",
    phone: "+91 98765 43210", // Editable placeholder
    whatsapp: "919876543210", // Editable numeric phone without +
    email: "contact@smtraders.com", // Editable placeholder
    address: "Main Road, Near Power Station, City, India", // Editable placeholder
    mapsUrl: "https://maps.google.com",
    social: {
      instagram: "https://instagram.com",
      facebook: "https://facebook.com"
    },
    images: {
      logo: "", // Custom logo image URL if available
      hero: "https://images.unsplash.com/photo-1613665813446-82a78c468a1d?q=80&w=1200", // High-res solar/electrical image
      solar: "https://images.unsplash.com/photo-1508873696983-2df515122519?q=80&w=1200",
      before: "https://images.unsplash.com/photo-1544725176-7c40e5a71c5e?q=80&w=800",
      after: "https://images.unsplash.com/photo-1621905251189-08b45d6a269e?q=80&w=800",
      mangesh: "https://images.unsplash.com/photo-1560250097-0b93528c311a?q=80&w=400",
      omkar: "https://images.unsplash.com/photo-1519085360753-af0119f7cbe7?q=80&w=400"
    }
  };
//

body.script:
//
  document.addEventListener('DOMContentLoaded', function() {
    // 1. Apply Dynamic SM_CONFIG values to UI elements
    if (typeof SM_CONFIG !== 'undefined') {
      var phoneClean = SM_CONFIG.phone || '+91 98765 43210';
      var whatsappNum = SM_CONFIG.whatsapp || '919876543210';
      var whatsappBaseUrl = 'https://wa.me/' + whatsappNum + '?text=' + encodeURIComponent('Hello SM Traders, I have an enquiry regarding electrical/solar services.');

      var contactPhoneLink = document.getElementById('contactPhoneLink');
      if (contactPhoneLink) {
        contactPhoneLink.textContent = phoneClean;
        contactPhoneLink.href = 'tel:' + phoneClean.replace(/[^0-9+]/g, '');
      }

      var barCallLink = document.getElementById('barCallLink');
      if (barCallLink) {
        barCallLink.href = 'tel:' + phoneClean.replace(/[^0-9+]/g, '');
      }

      var contactAddressText = document.getElementById('contactAddressText');
      if (contactAddressText && SM_CONFIG.address) {
        contactAddressText.textContent = SM_CONFIG.address;
      }

      ['floatingWhatsappBtn', 'contactWhatsappLink', 'barWhatsappLink'].forEach(function(id) {
        var el = document.getElementById(id);
        if (el) el.href = whatsappBaseUrl;
      });
    }

    // 2. Mobile Menu Drawer Toggle
    var openBtn = document.getElementById('mobileNavOpen');
    var closeBtn = document.getElementById('mobileNavClose');
    var drawer = document.getElementById('mobileDrawer');
    var drawerLinks = document.querySelectorAll('.drawer-link');

    function openDrawer() {
      if (drawer) {
        drawer.classList.add('open');
        document.body.style.overflow = 'hidden';
      }
    }

    function closeDrawer() {
      if (drawer) {
        drawer.classList.remove('open');
        document.body.style.overflow = '';
      }
    }

    if (openBtn) openBtn.addEventListener('click', openDrawer);
    if (closeBtn) closeBtn.addEventListener('click', closeDrawer);

    drawerLinks.forEach(function(link) {
      link.addEventListener('click', closeDrawer);
    });

    document.addEventListener('keydown', function(e) {
      if (e.key === 'Escape' && drawer && drawer.classList.contains('open')) {
        closeDrawer();
      }
    });

    // 3. Solar Estimate Calculator Logic
    var calcForm = document.getElementById('solarCalcForm');
    var calcResultArea = document.getElementById('calcResultArea');
    var calcResultText = document.getElementById('calcResultText');

    if (calcForm) {
      calcForm.addEventListener('submit', function(e) {
        e.preventDefault();
        var bill = parseFloat(document.getElementById('calcBill').value) || 0;
        var prop = document.getElementById('calcProperty').value;

        var estKw = Math.max(1, Math.round(bill / 1200));
        var minKw = Math.max(1, estKw);
        var maxKw = estKw + 2;

        if (calcResultText && calcResultArea) {
          calcResultText.textContent = 'Indicative Requirement: ' + minKw + ' kW - ' + maxKw + ' kW Solar Setup (' + prop + ')';
          calcResultArea.classList.add('active');
        }
      });
    }

    // 4. Portfolio Filter Tabs
    var filterBtns = document.querySelectorAll('.filter-btn');
    var projectCards = document.querySelectorAll('.project-card');

    filterBtns.forEach(function(btn) {
      btn.addEventListener('click', function() {
        filterBtns.forEach(function(b) { b.classList.remove('active'); });
        btn.classList.add('active');

        var filter = btn.getAttribute('data-filter');

        projectCards.forEach(function(card) {
          var categories = card.getAttribute('data-category') || '';
          if (filter === 'all' || categories.indexOf(filter) !== -1) {
            card.style.display = 'flex';
          } else {
            card.style.display = 'none';
          }
        });
      });
    });

    // 5. Fullscreen Lightbox
    var lightboxModal = document.getElementById('lightboxModal');
    var lightboxImg = document.getElementById('lightboxImg');
    var lightboxTitle = document.getElementById('lightboxTitle');
    var lightboxTag = document.getElementById('lightboxTag');
    var lightboxDesc = document.getElementById('lightboxDesc');
    var lightboxCloseBtn = document.getElementById('lightboxCloseBtn');

    projectCards.forEach(function(card) {
      card.addEventListener('click', function() {
        var title = card.getAttribute('data-title');
        var tag = card.querySelector('.project-tag') ? card.querySelector('.project-tag').textContent : '';
        var desc = card.getAttribute('data-desc');
        var img = card.getAttribute('data-img');

        if (lightboxImg) lightboxImg.src = img;
        if (lightboxTitle) lightboxTitle.textContent = title;
        if (lightboxTag) lightboxTag.textContent = tag;
        if (lightboxDesc) lightboxDesc.textContent = desc;

        if (lightboxModal) {
          lightboxModal.classList.add('active');
          document.body.style.overflow = 'hidden';
        }
      });
    });

    function closeLightbox() {
      if (lightboxModal) {
        lightboxModal.classList.remove('active');
        document.body.style.overflow = '';
      }
    }

    if (lightboxCloseBtn) lightboxCloseBtn.addEventListener('click', closeLightbox);
    if (lightboxModal) {
      lightboxModal.addEventListener('click', function(e) {
        if (e.target === lightboxModal) closeLightbox();
      });
    }

    // 6. FAQ Accordion Toggle
    var faqHeaders = document.querySelectorAll('.faq-header');
    faqHeaders.forEach(function(header) {
      header.addEventListener('click', function() {
        var item = header.parentElement;
        var isOpen = item.classList.contains('active');

        document.querySelectorAll('.faq-item').forEach(function(i) {
          i.classList.remove('active');
        });

        if (!isOpen) {
          item.classList.add('active');
        }
      });
    });

    // 7. Contact Form WhatsApp Prefilled Message Fallback
    var contactForm = document.getElementById('contactForm');
    if (contactForm) {
      contactForm.addEventListener('submit', function(e) {
        e.preventDefault();
        var name = document.getElementById('contactName').value;
        var phone = document.getElementById('contactPhone').value;
        var service = document.getElementById('contactService').value;
        var location = document.getElementById('contactLocation').value;
        var msg = document.getElementById('contactMessage').value;

        var num = (typeof SM_CONFIG !== 'undefined' && SM_CONFIG.whatsapp) ? SM_CONFIG.whatsapp : '919876543210';

        var text = 'New Website Enquiry - SM Traders\n' +
                   'Name: ' + name + '\n' +
                   'Phone: ' + phone + '\n' +
                   'Service: ' + service + '\n' +
                   'Location: ' + (location || 'N/A') + '\n' +
                   'Details: ' + (msg || 'N/A');

        var waUrl = 'https://wa.me/' + num + '?text=' + encodeURIComponent(text);
        window.open(waUrl, '_blank');
      });
    }
  });
//
